  "data-structures-3": { cpp: "stack<char> st;\nfor (char c : s) {\n    if (c == '(') st.push(c);\n    else { if (st.empty()) return false; st.pop(); }\n}\nreturn st.empty();", python: "st = []\nfor c in s:\n    if c == '(': st.append(c)\n    elif st: st.pop()\n    else: return False\nreturn not st" },
