  "data-structures-9": { cpp: "int find(int v) { return parent[v] == v ? v : parent[v] = find(parent[v]); }\nvoid unite(int a, int b) {\n    a = find(a); b = find(b);\n    if (a == b) return;\n    if (sz[a] < sz[b]) swap(a, b);\n    parent[b] = a; sz[a] += sz[b];\n}", python: "def find(v):\n    while parent[v] != v:\n        parent[v] = parent[parent[v]]\n        v = parent[v]\n    return v" },
